Fix the bug in sumAll. The inner var total shadows the outer total, so sum always returns 0.

function sumAll(values) {
  var total = 0;
  values.forEach(function(v) {
    var total = total + v;
  });
  return total;
}

Fix the closure bug in getCounters. Using var in the for loop makes all closures capture the same variable, so all return n+1 instead of 1..n.

function getCounters(n) {
  const fns = [];
  for (var i = 1; i <= n; i++) {
    fns.push(function() { return i; });
  }
  return fns.map(f => f());
}

Fix getCity so it does not throw when address is null or missing. Return null for missing paths.

function getCity(user) {
  return user.address.city;
}

Fix sortNums. Default Array.sort is lexicographic so "10" < "2". Sort ascending numerically.

function sortNums(arr) {
  return [...arr].sort();
}

Fix contains. Array.indexOf returns 0 (falsy) when item is at index 0, causing false negatives. Return a boolean.

function contains(arr, item) {
  return arr.indexOf(item);
}

Fix isObject. typeof null === "object" in JavaScript, so null incorrectly passes the check. Return false for null.

function isObject(val) {
  return typeof val === "object";
}

Fix average. reduce without an initial value throws TypeError on empty array. Return 0 for empty input.

function average(nums) {
  return nums.reduce((sum, n) => sum + n) / nums.length;
}

