Backoff is handled. What named safeguard is missing that would prevent double charges if the gateway charges successfully but the response is lost?

async function retryPayment(userId, amount, requestId) {
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      if (attempt > 0) await sleep(attempt * 1000);
      return await paymentGateway.charge(userId, amount);
      // requestId is passed in but never used
    } catch (err) {
      if (attempt < 2) continue;
      throw err;
    }
  }
}

What concurrency problem exists?

async function buyTicket(eventId) {
  const ticket = await db.findOne(
    "SELECT * FROM tickets WHERE event_id=? AND available=1", [eventId]
  );
  if (!ticket) return {error: "sold out"};
  await db.run(
    "UPDATE tickets SET available=0 WHERE id=?", [ticket.id]
  );
  return {success: true};
}

